302	  /**
303	   * A restart is the only way to change the model, since --model is a launch flag, not a
304	   * live setting. Mid-turn, that restart would kill the turn, so the pane must wait for
305	   * idle. The session id carries over, so the restarted child resumes the conversation.
306	   */
307	  setModel(model: string, advisor: string | null) {
308	    if (this.busy) throw new Error('wait for the current turn to finish before switching models')
309	    this.model = model
310	    this.advisor = advisor
311	    if (!this.proc) return
312	    this.switching = true
313	    this.switchLabel = `Switched to ${model}${advisor ? ` + ${advisor} advisor` : ''}.`
314	    this.proc.kill()
315	  }
