322	  onContext(cb: (c: Context) => void) {
323	    this.contextListeners.add(cb)
324	    return () => this.contextListeners.delete(cb)
325	  }
326	
327	  private notifyContext() {
328	    for (const cb of this.contextListeners) cb(this.context())
329	  }
330	
331	  /**
332	   * Drops the stored session and the visible transcript, so the next turn starts a
333	   * conversation the model has never seen. The map is untouched — only the chat forgets.
334	   */
335	  clearContext() {
336	    if (this.busy) throw new Error('wait for the current turn to finish before clearing the context')
337	    clearSession(this.dir)
338	    if (existsSync(this.chatPath)) rmSync(this.chatPath)
339	    this.contextUsed = 0
340	    this.notifyContext()
341	    if (!this.proc) return
342	    this.switching = true
343	    this.switchLabel = ''
344	    this.proc.kill()
345	  }
