367	  onBackground(cb: (t: BackgroundTask[]) => void) {
368	    this.backgroundListeners.add(cb)
369	    return () => this.backgroundListeners.delete(cb)
370	  }
371	
372	  /** Persisted. The transcript keeps this. */
373	  private emit(from: ChatMessage['from'], text: string, extra: Partial<ChatMessage> = {}) {
374	    const message: ChatMessage = { at: new Date().toISOString(), from, text, ...extra }
375	    mkdirSync(this.dir, { recursive: true })
376	    appendFileSync(this.chatPath, JSON.stringify(message) + '\n')
377	    for (const cb of this.listeners) cb(message)
378	  }
