  "version": "0.0.1",
  "private": true,
  "type": "module",
  "description": "A visual layer over Claude Code. An append-only decision log, folded into a map.",
  "bin": {
    "werk": "./src/cli.ts"
  },
  "scripts": {
    "werk": "bun src/cli.ts",
    "serve": "bun src/cli.ts serve",
    "dev": "bun --hot src/cli.ts serve",
    "test": "node src/permission.test.mjs",
    "test:live": "node src/permission.live.mjs"
  },
  "engines": {
    "bun": ">=1.4"
  }
}
